// ===================== CONFIGURAÇÃO (preencha uma vez) =====================
// Endereço do app das alunas, sem barra no fim. Ex.: https://app.lnobrega.com
const APP_URL = 'https://metodo.lnobrega.com';
// ===========================================================================
const SUPABASE_URL = 'https://ivfgpircfwwgpumrrcwp.supabase.co';
if (APP_URL.includes('COLE_AQUI')) throw new Error('Preencha o APP_URL no topo deste nó.');

// Lê as linhas da aba Importar: Nome | E-mail | WhatsApp | Data da compra (DD/MM/AAAA)
function dataIso(v) {
  const s = String(v || '').trim();
  const m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m) return `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}T12:00:00-03:00`;
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.length === 10 ? s + 'T12:00:00-03:00' : s;
  return new Date().toISOString();
}
const saida = [];
for (const item of $input.all()) {
  const l = item.json;
  const email = String(l['E-mail'] || '').toLowerCase().trim();
  if (!email || !email.includes('@')) continue;
  if (String(l['Resultado'] || '').startsWith('Acesso')) continue; // já importada antes
  saida.push({
    json: {
      email,
      nome: String(l['Nome'] || '').trim(),
      telefone: String(l['WhatsApp'] || '').trim(),
      data_compra: dataIso(l['Data da compra']),
      app_url: APP_URL.replace(/\/$/, ''),
      supabase_url: SUPABASE_URL,
    },
  });
}
if (!saida.length) throw new Error('Nenhuma aluna nova pra importar na aba Importar.');
return saida;

const TEXTOS = {
  nova: 'Acesso liberado (aluna nova)',
  renovada: 'Acesso renovado por 1 ano',
  sem_login: 'ERRO: login não criado. Confira o SMTP do Supabase',
};
return $input.all().map((item, i) => {
  const p = $('Preparar').itemMatching(i).json;
  let convite = 'Enviado';
  try {
    const c = $('Enviar convite').itemMatching(i).json;
    if (c.error) convite = /already|registered|email_exists/i.test(JSON.stringify(c.error)) ? 'Já tinha login' : 'Não enviado';
  } catch (e) {}
  const r = item.json.resultado;
  return { json: { 'E-mail': p.email, 'Resultado': (TEXTOS[r] || r || 'ERRO') + ' | e-mail: ' + convite } };
});
